INSERT INTO nutrient (id, code, name, en_name, unit, base_amount, group_code, display_order, base_unit, unit_factor, is_energy, description, enabled, created_at, updated_at) VALUES
  (1, 'ENERGY', '热量', 'Energy', 'kcal', 100, 'MACRO', 1, 'kcal', 1, 1, '食品中碳水化合物、蛋白质与脂肪在体内氧化可提供的能量总和。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (2, 'PROTEIN', '蛋白质', 'Protein', 'g', 100, 'MACRO', 2, 'g', 1, 0, '由氨基酸构成的大分子，是身体组织生长与修复的重要原料。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (3, 'FAT', '脂肪', 'Fat', 'g', 100, 'MACRO', 3, 'g', 1, 0, '提供能量并帮助脂溶性维生素吸收的一类营养素。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (4, 'CARBOHYDRATE', '碳水化合物', 'Carbohydrate', 'g', 100, 'MACRO', 4, 'g', 1, 0, '膳食中主要的供能营养素，包括糖、淀粉等。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (5, 'DIETARY_FIBER', '膳食纤维', 'Dietary Fiber', 'g', 100, 'MACRO', 5, 'g', 1, 0, '人体不能消化吸收的植物性成分，有助于肠道蠕动。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (6, 'SODIUM', '钠', 'Sodium', 'mg', 100, 'MINERAL', 6, 'mg', 1, 0, '维持体内水平衡与神经肌肉功能的矿物质，主要来自食盐。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (7, 'CALCIUM', '钙', 'Calcium', 'mg', 100, 'MINERAL', 7, 'mg', 1, 0, '构成骨骼与牙齿的主要矿物质，也参与多种生理过程。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (8, 'IRON', '铁', 'Iron', 'mg', 100, 'MINERAL', 8, 'mg', 1, 0, '参与血红蛋白携氧的微量元素，动物性食物中的铁更易吸收。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (9, 'POTASSIUM', '钾', 'Potassium', 'mg', 100, 'MINERAL', 9, 'mg', 1, 0, '维持细胞内外渗透压与正常心肌功能的矿物质。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (10, 'VITAMIN_A', '维生素A', 'Vitamin A', 'ug', 100, 'VITAMIN', 10, 'ug', 1, 0, '与视觉功能和上皮组织健康相关的脂溶性维生素。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (11, 'VITAMIN_C', '维生素C', 'Vitamin C', 'mg', 100, 'VITAMIN', 11, 'mg', 1, 0, '水溶性维生素，参与胶原合成，遇热与久放易损失。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (12, 'VITAMIN_D', '维生素D', 'Vitamin D', 'ug', 100, 'VITAMIN', 12, 'ug', 1, 0, '促进钙吸收的脂溶性维生素，日照与部分食物可提供。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (13, 'CHOLESTEROL', '胆固醇', 'Cholesterol', 'mg', 100, 'OTHER', 13, 'mg', 1, 0, '主要存在于动物性食物中的一类脂类物质。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (14, 'OMEGA3', 'Omega-3脂肪酸', 'Omega-3 Fatty Acids', 'g', 100, 'OTHER', 14, 'g', 1, 0, '一类多不饱和脂肪酸，深海鱼中含量相对丰富。', 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00');
INSERT INTO food (id, code, category_id, name, en_name, scientific_name, intro, common_usage, origin, storage_method, suitable_for, cautions, search_keywords, review_status, publish_status, published_at, created_by, updated_by, reviewed_by, reviewed_at, created_at, updated_at, deleted_at) VALUES
  (1, 'veg-tomato', 1, '西红柿', 'Tomato', 'Solanum lycopersicum', '西红柿，又名番茄，富含多种维生素和矿物质，是一种广泛受欢迎的蔬菜和水果，口感酸甜，营养丰富。', '生食、凉拌、炒食、煮汤', '全球广泛种植', '常温或冷藏', '一般人群均可食用', '未成熟的青西红柿含番茄碱，不宜大量生食', '西红柿 番茄 tomato 洋柿子', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (2, 'veg-cucumber', 1, '黄瓜', 'Cucumber', 'Cucumis sativus', '黄瓜是常见的瓜类蔬菜，水分含量高，口感清脆爽口，常作凉拌食用。', '凉拌、生食、炒食、腌制', '我国南北各地均有栽培', '冷藏', '一般人群均可食用', '脾胃虚寒者不宜一次大量生食', '黄瓜 青瓜 cucumber huanggua', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (3, 'veg-spinach', 1, '菠菜', 'Spinach', 'Spinacia oleracea', '菠菜是深绿色叶菜，叶片柔嫩，含有较丰富的叶酸与多种矿物质。', '焯水后凉拌、炒食、做汤', '我国各地普遍栽培', '冷藏', '一般人群均可食用', '含草酸较多，宜焯水后再烹调', '菠菜 波斯菜 spinach bocai', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (4, 'veg-carrot', 1, '胡萝卜', 'Carrot', 'Daucus carota', '胡萝卜是根茎类蔬菜，色泽橙黄，口感清甜脆嫩。', '炒食、炖煮、凉拌、榨汁', '我国南北各地均有栽培', '阴凉干燥处或冷藏', '一般人群均可食用', '与油脂同烹更利于其中脂溶性成分的吸收', '胡萝卜 红萝卜 carrot huluobo', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (5, 'veg-cabbage', 1, '白菜', 'Chinese Cabbage', 'Brassica rapa pekinensis', '白菜是我国北方常见的叶菜，叶球紧实，味道清甜，水分充足。', '炒食、炖煮、做馅、腌制', '我国北方为主要产区', '阴凉通风处或冷藏', '一般人群均可食用', '腌制制品含盐较高，宜适量食用', '白菜 大白菜 chinese cabbage baicai', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (6, 'veg-broccoli', 1, '西兰花', 'Broccoli', 'Brassica oleracea italica', '西兰花是十字花科蔬菜，花球紧密，色泽翠绿，口感脆嫩。', '焯水凉拌、清炒、蒸食', '我国多地均有栽培', '冷藏', '一般人群均可食用', '不宜长时间高温烹煮，以免口感与色泽变差', '西兰花 绿花菜 broccoli xilanhua', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (7, 'veg-potato', 1, '土豆', 'Potato', 'Solanum tuberosum', '土豆是重要的块茎类食物，淀粉含量较高，可作主食也可作菜。', '蒸煮、炒食、炖煮、烤制', '我国多地均有栽培', '阴凉避光处存放', '一般人群均可食用', '发芽或表皮变绿的土豆不宜食用', '土豆 马铃薯 potato tudou', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (8, 'veg-onion', 1, '洋葱', 'Onion', 'Allium cepa', '洋葱是葱蒜类蔬菜，气味辛香，炒熟后带有明显甜味。', '炒食、炖煮、凉拌、做汤', '我国多地均有栽培', '阴凉干燥通风处', '一般人群均可食用', '切制时气味刺激眼睛，可先冷藏再切', '洋葱 圆葱 onion yangcong', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (9, 'veg-garlic', 1, '大蒜', 'Garlic', 'Allium sativum', '大蒜是常用的调味类蔬菜，辛辣味明显，常作炝锅与腌渍用料。', '炝锅、腌制、捣泥调味', '我国多地均有栽培', '阴凉干燥通风处', '一般人群均可食用', '生食刺激性较强，不宜空腹大量食用', '大蒜 蒜头 garlic dasuan', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (10, 'veg-eggplant', 1, '茄子', 'Eggplant', 'Solanum melongena', '茄子是茄果类蔬菜，果肉松软，吸油性较强，烧制后口感绵软。', '红烧、蒸制、炒食、烤制', '我国多地均有栽培', '常温阴凉处或冷藏', '一般人群均可食用', '烹制时吸油较多，建议少油做法', '茄子 矮瓜 eggplant qiezi', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (11, 'fruit-blueberry', 2, '蓝莓', 'Blueberry', 'Vaccinium corymbosum', '蓝莓是小型浆果，果皮呈深蓝色，酸甜适中，可直接食用。', '生食、酸奶拌食、烘焙、制酱', '我国东北与西南高海拔地区有栽培', '冷藏', '一般人群均可食用', '表面白霜为天然果粉，清洗时不必用力搓洗', '蓝莓 笃斯 blueberry lanmei', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (12, 'fruit-apple', 2, '苹果', 'Apple', 'Malus domestica', '苹果是常见仁果，果肉脆甜多汁，全年供应稳定。', '生食、榨汁、烘焙、制酱', '我国多地均有栽培', '冷藏或阴凉处', '一般人群均可食用', '果核不宜食用', '苹果 apple pingguo', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (13, 'fruit-banana', 2, '香蕉', 'Banana', 'Musa acuminata', '香蕉是热带水果，果肉软糯香甜，食用方便。', '生食、奶昔、烘焙', '我国南方为主要产区', '常温存放，避免冷藏', '一般人群均可食用', '含糖量较高，宜适量食用', '香蕉 banana xiangjiao', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (14, 'meat-chicken-breast', 3, '鸡胸肉', 'Chicken Breast', 'Gallus gallus domesticus', '鸡胸肉是禽肉中脂肪较少的部位，肉质细嫩，蛋白质含量较高。', '煎制、水煮、清炒、烤制', '规模化养殖，各地均有供应', '冷藏或冷冻', '一般人群均可食用', '需彻底加热后食用，避免生熟交叉污染', '鸡胸肉 鸡脯肉 chicken breast jixiongrou', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (15, 'aquatic-salmon', 4, '三文鱼', 'Salmon', 'Oncorhynchus', '三文鱼肉色橙红，肌间脂肪较多，口感肥美。', '生食刺身、煎制、烤制、烟熏', '主要来自冷水海域养殖与捕捞', '冷藏或冷冻', '一般人群均可食用', '生食需确认符合生食标准；对本品过敏者避免食用', '三文鱼 大马哈鱼 鲑鱼 salmon sanwenyu', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (16, 'aquatic-bass', 4, '清蒸鲈鱼', 'Steamed Sea Bass', 'Lateolabrax japonicus', '清蒸鲈鱼是以鲈鱼为主料的蒸制菜肴，鱼肉细嫩，滋味清鲜。', '清蒸、红烧、煮汤', '我国沿海及河口水域均有出产', '冷藏，尽快食用', '一般人群均可食用', '需彻底加热；对鱼类过敏者避免食用', '清蒸鲈鱼 鲈鱼 steamed sea bass luyu', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (17, 'egg-chicken-egg', 5, '鸡蛋', 'Chicken Egg', 'Gallus gallus domesticus', '鸡蛋是常见的蛋类食品，蛋清与蛋黄结构分明，可蒸可炒。', '水煮、蒸蛋、煎炒、烘焙', '规模化养殖，各地均有供应', '冷藏', '一般人群均可食用', '对蛋类过敏者避免食用；宜彻底加热', '鸡蛋 鸡子 chicken egg jidan', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (18, 'grain-oat', 6, '燕麦', 'Oat', 'Avena sativa', '燕麦是常见的全谷物，膳食纤维含量较高，煮后口感黏稠。', '煮粥、冲泡、烘焙、搭配乳制品', '我国华北与西北为主要产区', '阴凉干燥密封保存', '一般人群均可食用', '对麸质敏感者应选择标注无麸质的产品', '燕麦 莜麦 oat yanmai', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (19, 'dairy-milk', 7, '牛奶', 'Milk', 'Bos taurus', '牛奶是常见的乳制品，呈乳白色液体，滋味温和。', '直接饮用、搭配谷物、烘焙、制作甜品', '规模化牧场供应', '冷藏', '一般人群均可食用', '乳糖不耐受者可选低乳糖产品；对乳蛋白过敏者避免食用', '牛奶 牛乳 milk niunai', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (20, 'nut-walnut', 8, '核桃', 'Walnut', 'Juglans regia', '核桃是常见的坚果，果仁油脂含量高，口感香脆略带涩味。', '生食、烘焙、入菜、制酱', '我国云南、新疆等地为主要产区', '阴凉干燥密封保存', '一般人群均可食用', '热量较高宜适量；对坚果过敏者避免食用', '核桃 胡桃 walnut hetao', 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
