  (461, 33, 13, 100, 'g', '每100g熟制可食部', 'ZERO', 0, 1, NULL, 'APPROVED', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (462, 33, 14, 100, 'g', '每100g熟制可食部', 'PRESENT', 8.5, 1, NULL, 'APPROVED', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL);
INSERT INTO knowledge_doc (id, title, category, summary, source_id, source_excerpt, applicable_scope, embedding_model, review_status, publish_status, published_at, valid_until, created_by, updated_by, reviewed_by, reviewed_at, created_at, updated_at, deleted_at) VALUES
  (1, '营养素基础知识：六大类营养素与能量', 'NUTRIENT', '介绍能量、蛋白质、脂肪、碳水化合物、膳食纤维、矿物质与维生素的基本作用。', 2, NULL, '成人一般人群', NULL, 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', '2028-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (2, '常见食品的营养特点与挑选储存', 'FOOD', '按蔬菜、水果、肉类、水产、蛋类、谷物、乳制品、坚果等分类说明营养特点。', 2, NULL, '一般消费者', NULL, 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', NULL, 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (3, '《中国居民膳食指南》核心理念：食物多样与平衡膳食', 'GUIDELINE', '围绕食物多样、谷类为主、多吃蔬果奶豆等公开膳食原则作常识性说明。', 3, NULL, '成人一般人群', NULL, 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', '2028-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (4, '烹调与加工对食品营养的影响', 'COOKING', '说明加热、切配、浸泡等处理方式对食材口感与营养成分的一般影响。', 2, NULL, '家庭烹调者', NULL, 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', NULL, 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (5, '营养数据常见问题：缺失值、零值与参考重量', 'FAQ', '解释为什么营养数据会出现「暂无数据」，以及参考重量口径的含义。', 1, '演示内容，无真实出处定位', '成人一般人群', NULL, 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', '2028-01-01 00:00:00', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (6, '食品安全与膳食搭配的基本注意事项', 'SAFETY', '介绍生熟分开、彻底加热、过敏原提示等常识性食品安全要点。', 4, NULL, '成人一般人群', NULL, 'APPROVED', 'PUBLISHED', '2025-01-01 00:00:00', NULL, 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL);
INSERT INTO knowledge_chunk (id, doc_id, chunk_index, heading, content, token_count, keywords, created_at, updated_at) VALUES
  (1, 1, 0, '营养素的基本分类', '食物中的营养素通常被分为六大类：碳水化合物、蛋白质、脂肪、矿物质、维生素和水，膳食纤维常被单独作为一类讨论。碳水化合物、蛋白质和脂肪在体内氧化后可以为身体提供能量，因此常被称为产能营养素；矿物质和维生素本身不提供能量，但参与身体多种代谢与调节过程。中国居民膳食指南提倡通过多样化的食物搭配来满足各类营养素的需要，而不是依赖单一食物或单一补充剂。需要说明的是，本演示文档只介绍公开的常识性概念，不涉及任何具体数值标准。', 312, '营养素 分类 产能营养素 矿物质 维生素', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (2, 1, 1, '蛋白质与氨基酸', '蛋白质由氨基酸构成，食物中的蛋白质在消化过程中被分解为氨基酸，再被身体用于合成自身的蛋白质。不同食物来源的蛋白质在氨基酸组成上并不相同，一般来说动物性食物和大豆类食物的氨基酸组成较为接近人体需要。日常膳食中把谷类与豆类、动物性食物搭配食用，是一种常见的做法。蛋白质的需要量因年龄、性别、身体状态和活动水平而异，具体数值应参考权威膳食指南或咨询专业人员，本演示数据不提供个体化建议。', 288, '蛋白质 氨基酸 食物搭配', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (3, 1, 2, '碳水化合物与膳食纤维', '碳水化合物是膳食中最主要、最经济的能量来源，主要包括淀粉和各类糖。全谷物、杂豆和薯类除了提供碳水化合物外，还能提供一定量的膳食纤维。膳食纤维不能被人体消化吸收，但有助于肠道蠕动和增加饱腹感，因此膳食指南通常建议适当增加全谷物和蔬菜水果的比例。需要提醒的是，任何单一营养素都不是越多越好，均衡搭配、总量适宜才是关键。本演示文档不给出任何具体摄入量数字。', 360, '碳水化合物 淀粉 膳食纤维 全谷物', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (4, 2, 0, '蔬菜与水果的营养特点', '蔬菜和水果的共同特点是水分含量较高、能量密度相对较低，同时能提供多种维生素、矿物质和膳食纤维。深色蔬菜如菠菜、西兰花等通常含有较丰富的胡萝卜素等成分。水果中的糖以果糖、葡萄糖和蔗糖为主，口感甜度较高。膳食指南一般建议餐餐有蔬菜、天天有水果，并注意种类多样化。烹调蔬菜时尽量缩短加热时间，可以减少水溶性维生素的损失。本演示数据中的所有数值仅供参考，不代表真实检测结果。', 278, '蔬菜 水果 维生素 膳食纤维', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (5, 2, 1, '肉类、水产与蛋类的营养特点', '肉类、水产和蛋类是膳食中优质蛋白质的重要来源。畜禽肉中不同部位的脂肪含量差异较大，例如鸡胸肉的脂肪含量通常低于鸡腿和五花肉。水产品除蛋白质外，部分深海鱼含有较多的多不饱和脂肪酸。蛋类的蛋白质氨基酸组成较为理想，蛋黄中还含有脂溶性维生素和磷脂。选购时应注意产品的新鲜度，加工时保证彻底加热。以上均为常识性描述，本演示数据不提供任何具体成分数值。', 274, '肉类 水产 蛋类 优质蛋白', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (6, 2, 2, '乳制品、大豆与坚果的营养特点', '乳制品是膳食钙的常见来源，同时提供蛋白质和一定量的脂肪。大豆及其制品既能提供蛋白质，也含有较多不饱和脂肪酸。坚果和种子类食物的脂肪含量普遍较高，但以不饱和脂肪酸为主，能量密度也较高，因此适合作为少量零食而非大量食用。对乳糖不耐受的人群，可以根据自身情况选择适宜的乳制品形式。以上内容为公开常识性表述，不构成任何医学或营养建议。', 248, '乳制品 大豆 坚果 钙', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (7, 3, 0, '食物多样，合理搭配', '膳食指南强调食物多样，建议每天的膳食包括谷薯类、蔬菜水果、畜禽鱼蛋奶和豆类食物，平均每天摄入的食物种类尽量多一些。食物多样是获得各类营养素的基础，任何一种单一食物都无法提供全部营养。在实际生活中，可以通过粗细搭配、荤素搭配、深浅色蔬菜搭配等方式提高食物多样性。本演示文档只介绍公开的膳食理念，不给出任何个体化的定量方案。', 338, '食物多样 合理搭配 膳食指南', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (8, 3, 1, '吃动平衡，保持适宜体重', '膳食指南提倡吃动平衡，即通过合理的膳食摄入与规律的身体活动来维持适宜的体重。久坐少动的生活方式与能量摄入过多同时存在时，体重容易增加。规律的身体活动不仅有助于能量平衡，也对整体健康有积极作用。各年龄段人群的活动形式可以不同，关键是养成长期习惯。本演示文档为常识性说明，不提供任何具体的运动处方或营养处方。', 231, '吃动平衡 身体活动 体重', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (9, 3, 2, '多吃蔬果、奶类、全谷与大豆', '膳食指南鼓励餐餐有蔬菜、天天吃水果，并提倡经常摄入奶类、全谷物和大豆制品。这些食物能提供膳食纤维、钙、优质蛋白质和多种维生素矿物质。把精制米面部分替换为全谷物和杂豆，是提高膳食纤维摄入的常见做法。对于特殊人群，如婴幼儿、孕妇和老年人，膳食安排应结合自身情况并咨询专业人员。本演示文档不给出任何具体摄入量推荐值。', 250, '蔬果 奶类 全谷物 大豆', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (10, 4, 0, '加热对营养与口感的影响', '加热可以改善食材的口感、杀灭部分微生物，同时也会造成一些营养素的损失。维生素C等水溶性且不耐热的成分，在长时间高温加热或反复加热时损失相对明显；而部分植物性食材经过加热后，某些成分反而更易被人体利用。因此烹调时常见的原则是：能快炒则不长时间炖煮，蔬菜先洗后切、尽量减少浸泡时间，以降低水溶性营养素的流失。以上为一般性常识，不涉及任何具体数据。', 260, '加热 烹调 维生素损失 口感', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (11, 4, 1, '切配、浸泡与储存的影响', '食材在切配后暴露面积增大，与水、空气接触的机会增加，水溶性维生素和部分易氧化成分的损失也会随之增加。长时间浸泡米、切碎的蔬菜久放，都会带来不必要的损失。合理的做法包括：蔬菜先洗后切、切后尽快烹调，米不宜反复搓洗和长时间浸泡。储存方面，叶菜类适合低温保湿保存，根茎类适合阴凉干燥处存放。以上为常识性建议，不构成任何专业指导。', 339, '切配 浸泡 储存 维生素', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (12, 4, 2, '不同烹调方式的一般比较', '蒸、煮、快炒、烤、炸等烹调方式各有特点。蒸和煮以水或蒸汽为传热介质，温度相对温和；快炒加热时间短，有利于保留不耐热的成分；烤制会带来特有的风味，但需注意避免表面焦糊；油炸温度高、用油量大，会明显提高成品的能量和脂肪含量。日常烹调中可以根据食材特性选择合适的做法，并注意控制用油和用盐量。本演示文档不提供任何具体营养数值。', 243, '蒸 煮 炒 烤 炸 用油', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (13, 5, 0, '为什么会出现「暂无数据」', '营养数据的采集需要可靠的检测或权威来源。当某个食品的某项营养素尚未完成录入或缺乏可信来源时，系统会把它标记为「缺失」，在页面上显示为「暂无数据」，而不是显示为 0。这样做的原因是：把未知当作零会导致统计结果被系统性低估，也可能误导用户。本演示数据集里刻意保留了一部分缺失项，用于验证前端「暂无数据」的渲染效果与统计口径。', 258, '缺失值 暂无数据 三态 统计口径', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (14, 5, 1, '零值与缺失值的区别', '零值表示该项营养成分经过确认确实为零，例如纯肉类的碳水化合物、植物性食物中的胆固醇等；缺失值表示尚未获得可靠数据。两者在数据库里用不同的状态标记区分，在页面上也应当有不同的呈现方式：零值可以正常参与求和与平均，缺失值则应排除在统计分母之外，并在界面提示数据不完整。用户端看到的「0」和「暂无数据」含义完全不同，这是营养数据展示中容易被忽略但很重要的一点。', 268, '零值 缺失值 区别 求和 平均', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (15, 5, 2, '参考重量的口径说明', '同一食品的生鲜状态与熟制状态，其营养成分会有明显差异，例如加热过程中水分蒸发会使部分成分在每百克中的含量发生变化。因此营养数值必须同时说明参考重量口径，例如「每100克可食部」或「每100克熟制可食部」。可食部比例指去掉不可食部分后剩余的重量占比，未录入该比例时系统会留空，而不是默认按 100% 计算。查看营养数据时，请先确认口径，再进行不同食品之间的比较。', 368, '参考重量 可食部 生熟差异 口径', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (16, 6, 0, '生熟分开与彻底加热', '处理生食和熟食时，建议使用不同的案板、刀具和容器，避免生食材上的微生物污染已经可以直接食用的食物。肉类、禽类、蛋类和水产品都应彻底加热至熟透后再食用。剩余食物应及时冷藏，再次食用前充分加热。这些做法属于日常食品安全常识，与任何特定的疾病预防或治疗无关。本演示文档不提供任何医学建议。', 214, '生熟分开 彻底加热 食品安全 冷藏', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (17, 6, 1, '过敏原与个体差异', '部分人群对特定食物存在过敏现象，常见的致敏食物包括蛋类、乳类、鱼类、甲壳类和坚果等。对已知过敏的食物应主动避免，并在选购加工食品时留意配料表。此外，乳糖不耐受等人群在摄入乳制品时可以根据自身情况调整摄入形式与数量。以上内容为一般性生活常识，具体健康问题请咨询专业医务人员，本演示内容不构成医学建议。', 242, '过敏原 乳糖不耐受 配料表 个体差异', '2025-01-01 00:00:00', '2025-01-01 00:00:00'),
  (18, 6, 2, '关于本演示数据集的说明', '本系统当前使用的是一套演示数据集，所有营养数值仅用于功能演示与自动化测试，并不代表真实食品的营养成分，也未逐条标注权威文献出处。数据来源表中登记的部分公开资料名称，仅作为「来源档案」示例存在，本数据集并未从中摘录具体数值、页码或链接。请注意：任何饮食安排都应以权威膳食指南和专业人员的意见为准，本演示数据严禁用于对外发布或作为营养建议的依据。', 260, '演示数据 来源 免责 禁止发布', '2025-01-01 00:00:00', '2025-01-01 00:00:00');
