  (465, 34, 3, 100, 'g', '每100g可食部', 'PRESENT', 0.2, 1, NULL, 'APPROVED', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
