  (467, 34, 5, 100, 'g', '每100g可食部', 'PRESENT', 0.4, 1, NULL, 'APPROVED', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
  (468, 34, 6, 100, 'g', '每100g可食部', 'PRESENT', 1.3, 1, NULL, 'APPROVED', 1, 1, 1, '2025-01-01 00:00:00', '2025-01-01 00:00:00', '2025-01-01 00:00:00', NULL),
