-- ---------------------------------------------------------------------------
-- 十一、自增序列重置（H2 2.x 显式插入不推进标识列，必须手工 RESTART）
-- ---------------------------------------------------------------------------
ALTER TABLE sys_role ALTER COLUMN id RESTART WITH 5;
ALTER TABLE sys_user ALTER COLUMN id RESTART WITH 4;
ALTER TABLE data_source ALTER COLUMN id RESTART WITH 6;
ALTER TABLE food_category ALTER COLUMN id RESTART WITH 11;
ALTER TABLE nutrient ALTER COLUMN id RESTART WITH 15;
ALTER TABLE food ALTER COLUMN id RESTART WITH 24;
ALTER TABLE food_alias ALTER COLUMN id RESTART WITH 33;
ALTER TABLE food_state_variant ALTER COLUMN id RESTART WITH 38;
ALTER TABLE nutrition_value ALTER COLUMN id RESTART WITH 512;
ALTER TABLE knowledge_doc ALTER COLUMN id RESTART WITH 7;
ALTER TABLE knowledge_chunk ALTER COLUMN id RESTART WITH 19;

-- 说明：sys_user_role 为复合主键、无自增列；sys_auth_token / user_profile / food_image /
-- chat_session / chat_message / image_recognition / user_favorite / admin_audit_log /
-- operation_log 本次未插入任何数据，故无需也不应重置其自增序列。

